size=16
cell=glyph
align=cell
shift=0
range.basic-latin=original
advance.basic-latin=game
[font.0:clut8]
face=hterm16,ui
size=16
cell=glyph
align=cell
shift=0
range.basic-latin=original
advance.basic-latin=game
[font.0]
